mapper.update:
update T_TC_SCHEDULE_RESULT
set IS_DELETE = 1,
    UPDATE_TIME = now()
where IS_DELETE = 0
  and FACTORY_CODE = #{factoryCode}
  and SCHEDULE_DATE = #{scheduleDate}

mapper.select:
SELECT *
FROM T_TC_SCHEDULE_RESULT
WHERE FACTORY_CODE = #{factoryCode}
  AND SCHEDULE_DATE = #{scheduleDate}
  AND BATCH_NO = #{batchNo}
ORDER BY ID
FOR UPDATE
